fn polar_to_cartesian(polar: (Float64, Float64)) -> (Float64, Float64) {
  let (r, theta) = polar;
  let x = r * math.cos(theta);
  let y = r * math.sin(theta);
  return (x, y);
}

fn main() -> Int {
  let (x, y) = polar_to_cartesian((1.0, 1.570796));
  return (x * 10.0) as Int;
}
